mapper.update:
UPDATE PASS
   SET PNAME=#{pname},PPRICE=#{pprice},PTYPE=#{ptype},PPERIOD=#{pperiod, jdbcType=INTEGER},PCOUNT=#{pcount, jdbcType=INTEGER},
   		   	   PIMG=#{pimg},PINFO=#{pinfo}
 WHERE PNO=#{pno}

mapper.select:
SELECT *
  FROM (
  	SELECT INNER_LIST.*, ROWNUM AS RNUM
  	  FROM (
  	  	SELECT * 
  	  	  FROM PASS 
  	  	 ORDER BY PNO DESC
  	  ) INNER_LIST
  )
 WHERE RNUM BETWEEN #{startRow} AND #{endRow}
